 "content": "from math import gcd
from functools import reduce

def transform(grid):
    h, w = len(grid), len(grid[0])
    key_cells = [(r, c) for r in range(h) for c in range(w) if grid[r][c] not in (0, 8)]
    target_cells = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 8]
    if not key_cells or not target_cells:
        return [row[:] for row in grid]

    kr0, kr1 = min(r for r, c in key_cells), max(r for r, c in key_cells)
    kc0, kc1 = min(c for r, c in key_cells), max(c for r, c in key_cells)
    key = [[grid[r][c] for c in range(kc0, kc1 + 1)] for r in range(kr0, kr1 + 1)]
    # The color legend is rotated clockwise and enlarged over the 8-pattern.
    key = [list(row) for row in zip(*key[::-1])]

    lengths = []
    for r in range(h):
        cs = [c for rr, c in target_cells if rr == r]
        if cs:
            cs.sort()
            run = 1
            for a, b in zip(cs, cs[1:]):
                if b == a + 1:
                    run += 1
                else:
                    lengths.append(run)
                    run = 1
            lengths.append(run)
    for c in range(w):
        rs = [r for r, cc in target_cells if cc == c]
        if rs:
            rs.sort()
            run = 1
            for a, b in zip(rs, rs[1:]):
                if b == a + 1:
                    run += 1
                else:
                    lengths.append(run)
                    run = 1
            lengths.append(run)
    scale = reduce(gcd, lengths)

    tr0 = min(r for r, c in target_cells)
    tc0 = min(c for r, c in target_cells)
    out = [row[:] for row in grid]
    for r, c in target_cells:
        rr, cc = (r - tr0) // scale, (c - tc0) // scale
        if rr < len(key) and cc < len(key[0]):
            out[r][c] = key[rr][cc]
    return out
